cd /tmp/hwpx_work/template_contents && python3 -c "import zipfile, os; zf = zipfile.ZipFile('/root/project_proposal_ready.hwpx', 'w', zipfile.ZIP_DEFLATED); 
for root, dirs, files in os.walk('.'):
    for f in files:
        if f.startswith('.'): continue
        path = os.path.join(root, f)
        arcname = os.path.relpath(path, '.')
        zf.write(path, arcname)
zf.close()
print('Created /root/project_proposal_ready.hwpx')"
